import{z as i,x as A,o as t,c as C,q as E,j as o,D as e,d as l,s as n,S as s}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"SPC 与控制图","description":"","frontmatter":{"title":"SPC 与控制图","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/spc-control-chart.md","filePath":"litho/spc-control-chart.md","lastUpdated":1791413859000}'),p={name:"litho/spc-control-chart.md"};function B(h,a,P,d,S,c){const r=A("Mermaid");return t(),C("div",null,[a[2]||(a[2]=E('<h1 id="spc-与控制图" tabindex="-1">SPC 与控制图 <a class="header-anchor" href="#spc-与控制图" aria-label="Permalink to &quot;SPC 与控制图&quot;">​</a></h1><div class="epigraph"><p>控制图问的是过程是否仍是同一个过程；规格问的是这一片能不能出货。把规格线画在控制图上当判异规则，两种错误会一起犯。</p><footer>—— 对照 Shewhart 控制图传统；SEMI 与半导体厂对 SPC 的通称</footer></div><p><a href="/litho/sampling-plan">上一课</a>给出看见什么。缺口是判决：这些点何时算受控漂移（交给 APC）、何时算异常（停机、重工、排除数据）。本课钉 SPC 与控制图。套刻专用回路，留给<a href="/litho/overlay-control-loop">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Shewhart 图用过程自身的 \\(\\sigma\\) 建控制限，检测均值/方差偏移。规格限来自窗口与电学，通常宽得多。过程可以受控却能力不足（限很窄的悬崖），也可以能力充足却失控（突发指纹）。光刻上：剂量缓慢老化应 APC；突然的镜头污染或错版应 SPC 停。混用两条限，APC 会去「补偿」一次装版错误，把后续批带进沟里。</p><p><span class="marginnote">直觉类比：控制限像你自己的体温基线（问「还是不是同一个你」），规格限像入职体检标准（问「能不能上岗」）。体温正常但过不了体检，是能力问题；体温突然飙高，是「你变了」的问题——两种情况的处理动作完全不同。</span></p>',6)),(t(),o(s,null,{default:e(()=>[n(r,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20PT%5B%22%E6%96%B0%E6%95%B0%E6%8D%AE%E7%82%B9%22%5D%20--%3E%20CTL%7B%22%E6%8E%A7%E5%88%B6%E9%99%90%E5%86%85%EF%BC%9F%22%7D%0A%20%20CTL%20--%3E%7C%22%E5%87%BA%E9%99%90%22%7C%20SPC%5B%22SPC%20%E4%BA%8B%E4%BB%B6%EF%BC%9A%E5%81%9C%E6%9C%BA%20%2F%20%E6%89%A3%E7%95%99%20%2F%20%E6%9F%A5%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20CTL%20--%3E%7C%22%E5%8F%97%E6%8E%A7%22%7C%20SPEC%7B%22%E8%A7%84%E6%A0%BC%E9%99%90%E5%86%85%EF%BC%9F%22%7D%0A%20%20SPEC%20--%3E%7C%22%E6%98%AF%22%7C%20SHIP%5B%22%E5%8F%AF%E5%87%BA%E8%B4%A7%22%5D%0A%20%20SPEC%20--%3E%7C%22%E5%90%A6%22%7C%20CAP%5B%22%E5%8F%97%E6%8E%A7%E4%BD%86%E8%83%BD%E5%8A%9B%E4%B8%8D%E8%B6%B3%EF%BC%9A%E6%94%B9%E5%B7%A5%E8%89%BA%E6%88%96%E9%87%8D%E5%BB%BA%E9%99%90%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E('<p>缺口是<strong>异常与补偿的分工</strong>，不是重讲 3σ。Western Electric / Nelson 规则在光刻要谨慎：自相关（R2R 已补过的数据）会让规则误报。应用残差图（补偿后）做 SPC，而不是对原始 CD 再报一次 APC 已知的斜坡。</p><h3 id="多参数不是多张独立图" tabindex="-1">多参数不是多张独立图 <a class="header-anchor" href="#多参数不是多张独立图" aria-label="Permalink to &quot;多参数不是多张独立图&quot;">​</a></h3><p>CD 与套刻、X 与 Y、场心与边场相关。只看场平均 CD，边场弓形不报警。多元 SPC 或先看关键指纹的残差范数。本课不推 T² 公式，只要求判异对象与抽样、APC 项一致。</p><p><span class="marginnote">错因分层：轨道告警不要停扫描机；套刻失控不要先改剂量。控制图标题应是「谁的执行器」，不是「光刻」一个桶。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>图：I-MR、Xbar-R、残差 EWMA。分层：机台、腔体、产品、层。规则：限外、趋势、与事件对齐。动作：抑制 APC、触发加密抽样、批次扣留。与工具匹配：机台间差用匹配图，不当成单机失控。数据质量：SEM 收缩、配方换算法应换图，否则假失控。</p><p>控制限应在参考计量尺度上建立，并在匹配或算法升级后重建。Shewhart 传统假定独立同分布；光刻数据有自相关，故优先画补偿后残差，规则从简，事件对齐从严。</p><p><span class="marginnote">数字实例：过程 \\(\\sigma=1\\) nm 时，3σ 控制限是均值 \\(\\pm 3\\) nm。若 CD 规格宽到 \\(\\pm 10\\) nm，会出现「天天亮黄牌、从不超规格」；反过来规格若只有 \\(\\pm 1.5\\) nm，过程再受控也难出货——两条限各管各的事。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>受控过程仍有方差；控制限估计的是这方差。APC 降低了均值漂移后，残差 σ 可能下降，应重建限，否则过敏感。反过来，APC 饱和（打到限幅）应升格为 SPC 异常——能力或扰动已超出控制器。这是「不可再补」的操作定义。</p>',10)),(t(),o(s,null,{default:e(()=>[n(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22%E8%AE%A1%E9%87%8F%22%5D%20--%3E%20APC%5B%22R2R%20%E8%A1%A5%E5%81%BF%22%5D%0A%20%20APC%20--%3E%20RES%5B%22%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20RES%20--%3E%20SPC%5B%22%E6%8E%A7%E5%88%B6%E5%9B%BE%22%5D%0A%20%20SPC%20--%3E%20OK%5B%22%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20SPC%20--%3E%20HOLD%5B%22%E6%89%A3%E7%95%99%20%2F%20%E5%81%9C%E8%A1%A5%20%2F%20%E6%9F%A5%E4%BA%8B%E4%BB%B6%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=E('<p>补偿后残差才是受控与否的对象。规格限管出货；控制限管是否还是同一个过程。饱和即异常。</p><p><span class="marginnote">常见误区：拿 APC 补偿前的原始 CD 直接画图判异。R2R 已经把斜坡吃掉大半，原始数据充满自相关，趋势规则会连环误报；正确对象是补偿后的残差——看「补完之后还剩什么」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>SPC 不定位缺陷坐标（那是检测）。不把控制图当良率模型。不发明未公开的厂内规则条数。</p><p>后课默认：SPC 看补偿后残差与事件；限幅即异常。下一课把这套逻辑接到套刻网格。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>控制限与规格限分工：受控对出货。</li><li>SPC 应画 APC 残差；自相关数据不要套朴素规则。</li><li>控制器饱和即 SPC 事件。</li><li>出处：Shewhart 控制图；SEMI / 半导体 SPC 通称。</li></ul>',7))])}const D=i(p,[["render",B]]);export{_ as __pageData,D as default};
